  'elrs.feature.highSensitivity.title': '高灵敏度',
  'elrs.feature.highSensitivity.desc': 'LNA加持500Hz灵敏度-118dBm，实现以往只有亚GHz频段才能达到的2.4GHz远距离性能。',
  'elrs.feature.antiInterference.title': '抗干扰',
