  'elrsDetail.seoTitle': 'ELRS控制系统',

  'elrs.faq.q1': '为什么在工业无人机上使用双频（915MHz+2.4GHz）ELRS？',
  'elrs.faq.a1': '双频ELRS（如XK-915M）在Gemini模式下运行，可同时在915MHz和2.4GHz两个频段发送和接收控制信号。这显著增强了系统对单一频段干扰的抵抗能力，在城市建筑群或高压线等复杂电磁环境下，确保链路稳定性较单频系统提升200%以上。',
  'elrs.faq.q2': 'CaniUAV的ELRS系统是否支持MAVLink遥测？',
  'elrs.faq.a2': '是的。我们的双频及Nano系列接收机专为工业集成设计，通过标准串口与ArduPilot或PX4飞控通讯。其MAVLink封包速率远超传统硬件，可实时传回电池状态、GPS坐标等关键遥测数据。',
  'elrs.faq.q3': '433MHz与915MHz ELRS硬件如何选择？',
  'elrs.faq.a3': '433MHz具备极强的绕射能力，适合多障碍物（如林区、复杂地形）的短距通讯；而915MHz（或868MHz）则在天线尺寸与长距离传输（40km+）之间取得了最佳平衡，是目前远距离巡检无人机的首选方案。',


