  // About Business Ecosystem - upgraded to Full-Stack
  'about.ecosystem.title': '一站式定制模式',
  'about.ecosystem.desc': 'CANI 不仅卖模组，更提供固件编写、PCB 设计和整机系统集成服务。支持 OEM（你贴牌）、ODM（我设计）、一站式定制（你提需求，我搞定一切）。',
