  // Transportation Monitoring Solution Page - 智慧交通解决方案
  'transport.seo.title': '无人机交通监控解决方案 | 智慧城市与高速公路监控 | CANI UAV',
  'transport.seo.desc': 'CANI UAV智能交通监控解决方案。实时交通流量分析、事故检测与150公里加密高清视频链路，服务于高速公路与智慧城市基础设施。',
  'transport.seo.keywords': '空中交通监视,高速公路事故检测,无人机车辆跟踪计数,智慧城市空中基础设施,实时交通情报,桥梁结构检测无人机,BVLOS道路巡逻',
  'transport.badge': '智慧城市交通情报',
  'transport.title': '面向交通与运输监控的智能无人机解决方案',
  'transport.hero': '现代基础设施的空中之眼：城市化进程加速和高速公路网络不断扩展，要求交通管理采用更加动态化的方式。CANI UAV交通监控解决方案提供可扩展、高机动性的替代方案，突破固定CCTV网络的局限。依托W系列集群技术和TF2HD AI视觉模块，我们的无人机可监控数百公里公路——执行自动化交通流量分析、车辆计数和事故现场记录。通过150公里低延迟数字链路，指挥中心可实时接收偏远路段的1080P视频流，实现对拥堵或紧急事件的快速响应。',
  'transport.pain.title': '现代交通运营中的关键监控漏洞',
  'transport.pain.delay.title': '响应延迟',
  'transport.pain.delay.desc': '突发交通事故或严重拥堵时，地面巡逻车受困于车流，无法及时获取现场全景图像。固定CCTV网络存在覆盖盲区且维护成本高昂。',
  'transport.pain.blind.title': '结构盲点',
  'transport.pain.blind.desc': '特大桥底部支座、悬索节点及隧道出口周边是人眼和固定摄像头难以覆盖的盲区——人工检测需要高成本封锁车道。',
  'transport.pain.signal.title': '通信壁垒',
  'transport.pain.signal.desc': '山区高速与密集城市高层环境存在严重信号遮挡，民用图传系统5公里外即丢包或黑屏，导致偏远路段无法实时监控。',
  'transport.scenarios.title': '全场景交通情报与基础设施监测',
  'transport.scene1.title': '高速公路自动巡逻与实时交通流量分析',
  'transport.scene1.desc': '搭载CANI HD-1400-A150远距离数字链路和TF2HD AI视觉模块，单架次巡检无人机有效指挥半径可达150公里。K40T 40倍光学变焦相机可从安全高度识别车牌和检测路面缺陷。集成AI模块实现自主车辆统计、平均车速测算、多目标跟踪及逆行/违停自动取证——120km/h巡航速度下车辆识别准确率达91.8%。',
  'transport.scene2.title': '桥梁结构健康监测（SHM）',
  'transport.scene2.desc': '传统桥梁检测需封锁车道并使用昂贵的检测车。CANI方案利用搭载TF2A GPS拒止导航的无人机，实现不中断交通的精准作业。45MP高分辨率传感器生成亚毫米级正射图像，自动识别混凝土剥落、露筋及0.2mm级结构裂缝。TF2DU红外传感器以95.12%的准确率检测热异常。',
  'transport.vtx.link': '探索HD-1400 150公里远距离链路系统 →',
  'transport.adv.title': '专为智慧城市关键任务基础设施设计',
  'transport.adv.range.title': '150公里超稳定视频回传',
  'transport.adv.range.desc': 'HD-1400-A150先进射频放大技术，确保在高架立交、基站密集区及山区高速等复杂电磁环境下1080P/60fps加密视频流稳定传输。',
  'transport.adv.edge.title': 'TF2HD AI边缘计算',
  'transport.adv.edge.desc': '无需昂贵云端处理。TF2HD AI模块在机载端完成实时交通分析、车辆识别和事故检测，仅回传关键预警数据，节省80%带宽。',
  'transport.adv.reliable.title': '全天候可靠性',
  'transport.adv.reliable.desc': '工业级IP55防护与防腐蚀涂层，确保在沿海大桥高盐雾环境、40℃高温路面及恶劣天气条件下持续作业。',
  'transport.faq.title': '常见问题',
  'transport.faq.q1': 'CANI无人机在没有GPS的情况下能否在桥面下保持精确飞行？',
  'transport.faq.a1': '可以。TF2A AI引擎采用视觉里程计与IMU传感器融合技术实现无GPS导航，确保在桥底和隧道内无需卫星信号即可稳定悬停和亚厘米级路径跟踪。',
  'transport.faq.q2': '系统如何应对山区高速公路的信号遮挡？',
  'transport.faq.a2': 'HD-1400-A150在150公里范围内提供卓越的链路预算。结合定向地面天线和C波段频率隔离技术，即使在山区道路常见的地形障碍和多径干扰下，也能保持稳定的加密高清视频传输。',
  'transport.cta.title': '获取智慧交通解决方案',
  'transport.cta.subtitle': '联系我们的专业团队，获取智能交通无人机应用方案及投资回报分析',
  'transport.cta.btn': '立即咨询',
  'transport.whitepaper.btn': '下载智慧交通方案白皮书',

