  'softwarePage.pvInspection.anomaly.title': '光伏异常术语表',
  'softwarePage.pvInspection.anomaly.desc': '工程师级故障诊断参考，覆盖主要光伏热成像异常类型及AI处理策略。',
  'softwarePage.pvInspection.anomaly.hotspot.title': '热斑异常 (Hotspots)',
  'softwarePage.pvInspection.anomaly.hotspot.desc': '由电池片损坏、短路或阴影遮挡引起的局部过热。温差超过20°C视为高危故障，系统自动标记并生成优先级修复工单。',
  'softwarePage.pvInspection.anomaly.string.title': '组串故障 (String Outages)',
  'softwarePage.pvInspection.anomaly.string.desc': '整排面板异常温升或温降，通常与电气连接、断路器或逆变器问题相关。此类故障对IRR影响最大（可达249个基点），属于运维最高优先级。',
  'softwarePage.pvInspection.anomaly.diode.title': '旁路二极管异常 (Diode Anomalies)',
  'softwarePage.pvInspection.anomaly.diode.desc': '导致面板1/3区域过热，软件通过热成像分区分析精准定位该精细故障，区分二极管短路与开路两种模式。',
  'softwarePage.pvInspection.anomaly.soiling.title': '污染与遮挡 (Soiling & Shading)',
  'softwarePage.pvInspection.anomaly.soiling.desc': '尘埃堆积、植被遮挡或积雪导致的发电效率下降。通过RGB与IR双光谱对比分析，自动给出清洗建议与经济性评估。',
  'softwarePage.pvInspection.anomaly.crack.title': '隐裂 (Microcracks)',
  'softwarePage.pvInspection.anomaly.crack.desc': '电池片内部的微裂纹，初期不影响发电但会随温度循环扩展。EL检测+热成像联合分析可实现早期预警。',
  'softwarePage.pvInspection.anomaly.junction.title': '接线盒异常 (Junction Box Faults)',
  'softwarePage.pvInspection.anomaly.junction.desc': '接线盒过热通常由连接松动或密封失效引起，热成像可检测明显温升区域，防止火灾风险。',

