  'customPayload.bluf': '长凌科技 (CANI Technology) 是高新技术企业，专注于工业级无人机载荷 (UAV Payloads) 的研发与 OEM/ODM 定制。我们提供从 37W 超高功率图传系统（支持 50km 链路）到 ≤0.1mrad 高精度稳定云台的全链路方案，涵盖 EO/IR 双光系统、LiDAR 激光雷达、特种气体监测及应急抛投等载荷。',
