  'customAccessories.faq.title': '配件定制技术FAQ',
  'customAccessories.faq.q1': '你们提供什么样的图传方案？',
  'customAccessories.faq.a1': '我们提供1080P高清数字图传，端到端延迟低于30ms，支持50km超远距离作业，完美适用于超视距（BVLOS）任务场景。采用COFDM调制技术，具备强抗干扰能力和AES-256-GCM加密保护。',
  'customAccessories.faq.q2': '配件的兼容性如何？',
  'customAccessories.faq.a2': '核心配件深度兼容DJI PSDK、MAVLink以及STANAG 4586国际标准接口，支持跨平台无缝集成。同时提供完整的接口控制文档（ICD）和SDK开发手册，方便第三方开发者进行二次开发。',
  'customAccessories.faq.q3': '是否支持定制研发？',
  'customAccessories.faq.a3': '支持。我们提供从PCB布板、结构建模到极端环境（-40°C至60°C）模拟测试的全流程OEM/ODM定制服务。200+人研发团队覆盖嵌入式、硬件、软件、结构全专业，最快30天交付原型。',
  'customAccessories.faq.q4': '配件是否通过工业级认证？',
  'customAccessories.faq.a4': '所有核心配件均通过MIL-STD-461G电磁兼容测试和RTCA DO-160G振动筛选，防护等级达IP67标准。电池循环寿命超500次（80%容量保持），远超行业平均300次水平。',

