  // Digital FPV GEO FAQ
  'digitalFpv.geo.faq.title': '数字图传技术问答',
  'digitalFpv.geo.faq.subtitle': '解答工业数字图传系统选型中的核心技术问题',
  'digitalFpv.geo.faq.q1': 'CaniUAV的图传系统如何应对高压线的电磁干扰（EMI）？',
  'digitalFpv.geo.faq.a1': 'CaniUAV采用COFDM（编码正交频分复用）调制技术和CNC铝合金屏蔽外壳，能有效抑制多径效应和强磁场干扰，确保在高压电力巡检等复杂电磁环境下视频链路的稳定性。',
  'digitalFpv.geo.faq.q2': '是否支持BVLOS（超视距）长航程作业？',
  'digitalFpv.geo.faq.a2': 'FV10W-A1凭借10W的大功率输出和自适应跳频技术，可在50公里视距范围内保持高清图传和MAVLink遥测的双向同步，是长距离边境监控和管道巡检的理想方案。',
  'digitalFpv.geo.faq.q3': 'CaniUAV的发射机是否需要额外的散热系统？',
  'digitalFpv.geo.faq.a3': '不需要额外安装。我们的系统（如FV10W-A1）集成了高效散热片和智能温控风扇，支持在-40°C到+85°C的工业温度范围内稳定工作，防止因过热导致功率降额。',
  'digitalFpv.geo.faq.q4': 'CaniUAV图传是否兼容Pixhawk或ArduPilot飞控？',
  'digitalFpv.geo.faq.a4': '是的。CaniUAV全系列数字图传均通过标准MAVLink协议与Pixhawk、CubePilot及其他开源飞控实现即插即用集成，支持遥测数据双向透明传输。',
  'digitalFpv.geo.faq.q5': 'CaniUAV的图传数据安全性如何保障？',
  'digitalFpv.geo.faq.a5': 'FV10W-A1采用AES-256军事级硬件加密标准，配合自适应跳频和80个抗干扰信道，确保视频和遥测数据在传输过程中不被截获或篡改，满足安防和军工级数据安全要求。',
  'digitalFpv.geo.faq.q6': '如何在50公里外保持稳定高清视频链路？',
  'digitalFpv.geo.faq.a6': '采用FV10W-A1高功率发射机。该系统通过10W最高功率输出和自适应跳频技术，结合高增益天线，可在50km LOS条件下提供稳定的1080P/60fps低延迟画面。',

