  'gimbal.k8tv2.whitepaper.title': '📚 技术白皮书：V2算法——162g如何实现军工级增稳',
  'gimbal.k8tv2.whitepaper.desc': 'K8T-V2如何在162g载荷中实现±0.01°增稳、60°/s高速机动补偿？深入了解V2防抖逻辑、双光融合架构与低功耗侦察链路设计。',
  'gimbal.k8tv2.whitepaper.cta': '阅读深度技术解析',
  'gimbal.k8tv2.crossVtx.title': '🔗 最大化战术距离：K8T-V2 + 大功率图传',
  'gimbal.k8tv2.crossVtx.desc': '将K8T-V2紧凑型战术载荷与我们的FV10W/FV16W超大功率图传搭配，实现20公里以上的实时双光画面回传。当敏捷遇上极端距离，每一个热异常都能被即时捕获。',
  'gimbal.k8tv2.crossVtx.btn': '探索图传系统',
  'gimbal.k8tv2.crossSwarm.title': '🚁 推荐平台：紧凑型侦察无人机',
  'gimbal.k8tv2.crossSwarm.desc': 'K8T-V2专为每一克都至关重要的轻量化平台优化。探索我们的C系列和W系列紧凑型无人机，作为K8T-V2即插即用战术侦察载荷的最佳搭档。',
  'gimbal.k8tv2.crossSwarm.btn': '查看兼容平台',
  'gimbal.k8tv2.faq.q1': 'V2算法升级相比上一代有什么优势？',
  'gimbal.k8tv2.faq.a1': 'V2增稳算法自动对焦响应速度提升30%，高速机动（最高60°/s）下的防抖性能显著增强。同时增强了弱光追踪能力，确保在黄昏或黎明条件下也能稳定锁定目标。',
  'gimbal.k8tv2.faq.q2': 'K8T-V2能安装在7寸或10寸小型机架上吗？',
  'gimbal.k8tv2.faq.a2': '可以。K8T-V2仅162g，专为紧凑型机架设计。采用标准安装孔位，支持MAVLink/S.Bus协议，可即插即用适配Pixhawk、ArduPilot等主流飞控。',
  'gimbal.k8tv2.faq.q3': '测温范围和精度是多少？',
  'gimbal.k8tv2.faq.a3': '集成红外热传感器覆盖-20°C至650°C，精度±2°C（或±2%），NETD≤50mK灵敏度，可检测电力线路、管道和光伏板的细微热异常。',
  'gimbal.k8tv2.faq.q4': 'K8T-V2和K40T如何选择？',
  'gimbal.k8tv2.faq.a4': 'K8T-V2定位"紧凑敏捷"——针对快速部署和轻量化平台优化。K40T定位"极端距离"——为2公里以上战略远程侦察设计，配备40倍光学变焦。需要近距精检速度选K8T-V2；需要远距离隔离观察选K40T。',
  'gimbal.k8v2.name': 'K8-V2紧凑型高精度变焦云台',
  'gimbal.k8v2.slogan': '高效视觉智能 小型平台利器',
  'gimbal.k8v2.subSlogan': 'K8-V2：8倍光学变焦高精度紧凑型云台',
  'gimbal.k8v2.feature.resolution': '4K超高清',
  'gimbal.k8v2.feature.weight': '115g超轻量',
  'gimbal.k8v2.feature.aiTracking': 'AI追踪',
  'gimbal.k8v2.highlight.1': '115g超轻量——最大限度减少小型无人机载荷影响，延长飞行时间',
  'gimbal.k8v2.highlight.2': '30倍光学+8倍数码变焦，V2高速自动对焦实现瞬间细节捕捉',
  'gimbal.k8v2.highlight.3': 'V2增稳算法±0.01°精度，360°无限位偏航旋转',
  'gimbal.k8v2.highlight.4': 'MAVLink/S.Bus/PWM/ONVIF即插即用——60秒适配任何机架',
  'gimbal.k8v2.desc.1': 'K8-V2是追求紧凑型高品质光学变焦的操作者的最佳选择——115g同级最轻量化设计',
  'gimbal.k8v2.desc.2': 'V2优化增稳算法提供丝滑云台控制、零延迟响应与即时启动，满足快速部署场景需求',
  'gimbal.k8v2.desc.3': 'Sony 1/2.8英寸CMOS传感器配合30倍光学变焦，在安全距离内捕获清晰4K画面，适用于日常基建巡检',
  'gimbal.k8v2.desc.4': '360°无限位偏航旋转与±0.01°增稳精度——即使激烈机动也能保持画面稳定',
  'gimbal.k8v2.desc.5': 'IP65全天候防护，HDMI/IP双路视频输出，内置GPS/GLONASS定位',
  'gimbal.k8v2.featureItem.1': 'Sony 1/2.8英寸CMOS——专业级弱光表现',
