  'gimbal.k8v2.crossVtx.desc': '将115g K8-V2与我们的FLYM-PV02W500-A1 2.5W图传搭配，打造最具性价比的中程侦察方案。最大变焦智能、最小重量代价——预算敏感型集成商的理想选择。',
  'gimbal.k8v2.crossVtx.btn': '查看2.5W图传详情',
  'gimbal.k8v2.faq.q1': 'K8-V2和K8T-V2有什么区别？',
  'gimbal.k8v2.faq.a1': 'K8-V2定位"纯可见光专家"——单传感器（仅可见光）云台，115g极致轻量化，最大化光学变焦性能。K8T-V2定位"双光热成像专家"——增加红外热成像实现全天候昼夜作业，162g。需要最佳变焦重量比选K8-V2；需要热检测能力选K8T-V2。',
  'gimbal.k8v2.faq.q2': 'K8-V2能适配Pixhawk和ArduPilot飞控吗？',
  'gimbal.k8v2.faq.a2': '完全可以。K8-V2支持MAVLink、S.Bus、PWM和Serial TTL协议，标准安装孔位，可即插即用适配Pixhawk、ArduPilot等主流开源飞控。',
  'gimbal.k8v2.faq.q3': '电力巡检的有效变焦距离是多少？',
  'gimbal.k8v2.faq.a3': '凭借30倍光学变焦（加8倍数码共240倍），K8-V2可在300-500米安全距离清晰识别绝缘子裂纹和导线断股，确保无人机在电磁场安全区域外作业。',
  'gimbal.k8v2.faq.q4': '115g重量包含快拆支架吗？',
  'gimbal.k8v2.faq.a4': '115g仅指云台相机本体。快拆支架额外增加约15-20g。含支架总载荷重量约130-135g，完全适配7寸至10寸紧凑型无人机机架。',
