  // S900 Datalink
  'digitalFpv.s900.name': 'S900 一体化数字数据链',
  'digitalFpv.s900.slogan': '工业级数传图传一体链路',
  'digitalFpv.s900.subSlogan': '12KM通信距离 | 915MHz FHSS跳频 | 点对多点组网 | MAVLink兼容',
  'digitalFpv.s900.description': 'S900是一款专业的一体化数字数据链，将双向遥测（MAVLink）、遥控指令和数据传输集成于21g的紧凑模块中。采用业界领先的SDR技术，在极低发射功率（20dBm）下实现远距离稳定通信。支持点对点、点对多点和中继组网——工业无人机平台的通信骨干。',
  'digitalFpv.s900.keyFeature.1': '12KM通信距离',
