  'digitalFpv.s900.feature.2.title': 'SDR先进技术',
  'digitalFpv.s900.feature.2.desc': '采用业界领先的软件定义无线电技术，在极低发射功率下实现远距离高速双向通信，简化机载射频架构。',
  'digitalFpv.s900.feature.3.title': 'FHSS抗干扰技术',
  'digitalFpv.s900.feature.3.desc': '915MHz频段FHSS自动跳频，具备强大的抗干扰能力，在复杂电磁环境下保持通信稳定。',
  'digitalFpv.s900.feature.4.title': '点对多点组网',
  'digitalFpv.s900.feature.4.desc': '支持点对点、点对多点和中继组网三种模式，适用于集群协调和多机编队管理。',
  'digitalFpv.s900.feature.5.title': '宽电压输入（2S-20S）',
  'digitalFpv.s900.feature.5.desc': '支持2S-20S宽电压输入，兼容从小型战术无人机到重载工业机等多种飞行平台。',
