  // Common Gallery
  'common.productGallery': '产品图片',
  'digitalFpv.wifilink2.name': 'WiFiLink2 高清数字视频链路',
  'digitalFpv.wifilink2.slogan': '高性价比工业级数字高清链路',
  'digitalFpv.wifilink2.subSlogan': 'OpenIPC/Ruby 双系统 | 1080P 90FPS | H.265 高效编码 | 即插即用',
  'digitalFpv.wifilink2.description': 'WiFiLink2 是一款基于 OpenIPC 开源平台的高清宽带数字视频链路系统。采用 SONY IMX415 4K 传感器与 H.265 高效编码，实现 1080P 90FPS 超低延迟传输。支持 UDP/TCP 移动端直连、内置 32G DVR 录像，兼容 Ruby FPV 双系统架构。以极致性价比为工业巡检、轻量化侦察及系统集成商提供专业级高清视觉方案。',
  'digitalFpv.wifilink2.keyFeature.1': '1080P 90FPS',
  'digitalFpv.wifilink2.keyFeature.2': 'H.265 编码',
  'digitalFpv.wifilink2.keyFeature.3': 'OpenIPC 开源',
  'digitalFpv.wifilink2.keyFeature.4': '移动端直连',
  'digitalFpv.wifilink2.feature.1.title': 'H.265 高效编码引擎',
  'digitalFpv.wifilink2.feature.1.desc': '采用 H.265/HEVC 编码标准，相比 H.264 节省 50% 带宽，在相同信道条件下实现更高画质与更远传输距离',
  'digitalFpv.wifilink2.feature.2.title': '超低延迟架构',
  'digitalFpv.wifilink2.feature.2.desc': '端到端延迟低至 80ms 级别，基于 5GHz WiFi 宽带技术，满足实时巡检与精细操控需求',
  'digitalFpv.wifilink2.feature.3.title': '宽电压工业级供电',
  'digitalFpv.wifilink2.feature.3.desc': '支持 3~6S 电池供电（9~30V），内置电压稳压与过压保护，兼容各类工业无人机平台',
  'digitalFpv.wifilink2.feature.4.title': '15g 极致轻量化',
  'digitalFpv.wifilink2.feature.4.desc': '天空端仅重 15g，对飞行平台载重几乎无影响，适合 7寸至 10寸轻型侦察机集成',
  'digitalFpv.wifilink2.feature.5.title': 'OpenIPC/Ruby 双系统',
