  'powerInspection.geo.anchor': 'CaniUAV的能源解决方案采用高分辨率640×512辐射式热传感器来识别变电站中的热点，并利用40倍光学变焦从安全距离（50米以上）检查绝缘子引脚。我们的系统针对高电磁干扰环境进行了屏蔽，确保在高压线路附近实现稳定的控制和1080P反馈。',

