  // ===== Tethered Page =====
  'tethered.page.seo.title': '系留无人机系统 | 24小时超长续航与应急通信基站 | CANI UAV',
  'tethered.page.seo.desc': 'CANI UAV 专业系留无人机系统，支持24/7全天候持续滞空。通过高压电缆不间断供电，集成光纤通信与大功率负载能力，适用于应急通信、大型活动安防及长期环境监测。',
  'tethered.page.seo.keywords': '系留无人机供电系统,应急通信无人机基站,24小时长航时无人机,系留光纤传输方案,高空监控系留平台,系留无人机系统,系留无人机平台,持久空中监视,高压供电链路,系留无人机厂家',
  'tethered.page.hero.title': '工业级系留无人机系统：24小时全天候不间断作业平台',
  'tethered.page.hero.subtitle': '突破航时限制，定义持久感知：CANI UAV 系留系统通过高性能合金供电电缆，将地面电源与飞行平台连接，实现从"分钟级"到"天级"的航时跃迁。集成光纤数据传输技术，确保超高清视频流在强干扰环境下零延迟、高安全传输。无论是作为临时移动基站恢复灾区通信，还是作为高空瞭望哨监控城市安全，CANI UAV 系留系统都是您最可靠的长效空中作业伙伴。',
