  // ===== SEO Content Optimization (Report) =====

  // Homepage SEO Intro
  'home.seoIntro': '长凌科技——10年深耕工业级无人机核心配件研发制造，专注数字图传、飞控电调、云台吊舱生产，服务全球500+合作伙伴，提供定制化无人机配件解决方案，高新技术企业，品质有保障。',
  'home.brandSummary': '长凌科技核心产品涵盖数字图传系统、飞控电调、云台吊舱三大系列，可满足工业巡检、安防监控、FPV竞速等多场景需求，作为专业无人机核心配件制造商，我们以技术创新赋能全球合作伙伴，提供一站式OEM/ODM定制服务，打造稳定、高效、可靠的无人机配件解决方案。',

  // Products Page SEO
  'products.seo.overview': '长凌科技产品中心，汇聚工业级无人机核心配件全系列产品，涵盖数字图传系统、飞控电调系统、云台吊舱三大核心品类，200+产品型号，适配多旋翼、固定翼等多种无人机机型，覆盖电力巡检、消防应急、FPV竞速、测绘勘探等全场景。所有产品经过严格质量检测，出厂合格率达99.8%，支持OEM/ODM定制，满足不同客户的个性化需求。',
  'products.seo.cat.vtx': '高清数字图传系列——采用罗杰斯4350B射频材料，低损耗、高稳定，延迟≤30ms，传输距离可达50km，适配工业巡检、FPV竞速等场景，多款型号可选。',
  'products.seo.cat.fcesc': '专业飞控电调系列——高精度控制、快速响应，适配各类工业无人机，支持自主航线规划，稳定性强，可根据机型定制参数，保障无人机稳定飞行。',
  'products.seo.cat.gimbal': '稳定云台吊舱系列——防抖设计，拍摄画面清晰稳定，适配高清拍摄需求，防水防尘，可应对复杂户外作业环境，广泛应用于安防、巡检等场景。',

  // VTX FAQ (AEO)
  'vtx.faq.title': '技术选型FAQ — 大功率模拟图传选择指南',
  'vtx.faq.q1': '为什么在某些任务中选择模拟VTX而非数字链路？',
  'vtx.faq.a1': '在茂密森林、隧道和城市峡谷等非视距（NLOS）环境中，模拟VTX提供卓越的信号穿透力和零延迟（<1ms）实时视频反馈。数字系统擅长远距离加密传输，但在信号遮挡环境中，模拟链路的瞬时视觉反馈无可替代。',
  'vtx.faq.q2': '37W大功率VTX是如何实现极端非视距传输的？',
  'vtx.faq.a2': '37W VTX采用定制功率放大器，支持4.9–7.2GHz全双频段，可穿透密集障碍物提供极强的信号覆盖。大功率输出搭配CNC铝合金热管理系统，确保在战术和工业侦察场景中长时间稳定运行。',
  'vtx.faq.q3': '模拟VTX是独立配件还是无人机系统的一部分？',
  'vtx.faq.a3': '我们的模拟VTX/VRX模块是完全独立的视频链路配件，通用兼容所有飞控（Betaflight、Ardupilot、PX4），可安装于任何机架。它们未集成至我们的自主集群或物流平台——这些平台使用专用数字网格网络。',
  'vtx.faq.q4': '产品是否支持OEM/ODM定制？',
  'vtx.faq.a4': '完全支持。可定制内容包括传输距离、功率档位、频率配置（step 1MHz）、外壳设计及接口协议。典型定制周期15-30个工作日。',
  'vtx.faq.q5': '大功率模拟VTX最适合哪些环境？',
  'vtx.faq.a5': '大功率模拟VTX在以下场景表现卓越：林冠巡护（卓越的植被穿透力）、地下隧道巡检（NLOS信号反射）、城市峡谷侦察（多径丰富环境），以及任何需要零延迟瞬时视觉反馈且不能接受数字处理延迟的战术场景。',
  'vtx.techDetail': '本大功率模拟VTX/VRX图传系统专为NLOS和极端远距离任务打造：传输频段4.9-7.2GHz全频段，输出功率0.1–37W可调，零延迟（<1ms）实时模拟反馈，工作温度-20℃~60℃。CNC铝合金散热外壳厚度2mm，散热效率提升40%，确保设备连续战术作业8小时无过热。',
  'vtx.techDetail.title': '技术参数解读',
  'vtx.caseStudy.title': '应用案例：战术林区巡护',
  'vtx.caseStudy.content': '某省林业局部署CANI 10W大功率模拟VTX用于密林林冠巡护作业。在150米高空穿过浓密植被时，系统提供清晰的实时视频和零延迟反馈，实现对非法砍伐和火灾热点的即时检测。模拟链路在此非视距环境中卓越的植被穿透力超越了数字替代方案，巡护覆盖率提升400%。',

  // FC/ESC SEO Content
  'fcesc.seo.intro': '长凌科技专业飞控电调系统，搭载STM32 H7自动驾驶仪（三重冗余IMU）和高压FOC电调（最高24S/200A），是工业无人机的"核心大脑"与"动力中枢"，为多旋翼、固定翼无人机提供高精度控制与稳定动力输出，适配电力巡检、消防应急、测绘勘探及超视距任务。',
  'fcesc.seo.intro.title': '产品简介',
  'fcesc.techDetail.title': '技术详情',
  'fcesc.techDetail': '飞控采用STM32H743/H753 MCU（480MHz），支持实时卡尔曼滤波和高频PID回路。三重冗余IMU（ICM-42688-P + BMI270）独立总线部署，毫秒级故障切换。电调搭载智能FOC矢量控制，80A-200A持续电流，DroneCAN/UART实时遥测，过温/过流/电机锁死多重保护。',
  'fcesc.caseStudy.title': '应用案例',
  'fcesc.caseStudy': '某无人机制造商使用我们的飞控电调系统，用于工业巡检无人机的生产装配，经过实际测试，无人机可实现自主航线规划、定点悬停、自动返航等功能，飞行稳定性提升60%，故障率降低至0.5%以下，大幅提升了产品竞争力，双方达成长期战略合作。',

