  'fcesc.h2.esc': '高压FOC电调：重型无人机的精确动力',
  'fcesc.h2.stacks': '专业FPV与航拍即插即用飞塔',

  // FC/ESC Category FAQ
  'fcesc.faq.title': '飞控与电调技术问答',
  'fcesc.faq.subtitle': '面向工业无人机系统集成商的飞控与电调专业技术问答。',
  'fcesc.faq.q1': '为什么工业无人机要选择H7飞控？',
  'fcesc.faq.a1': 'H7处理器（运行于480MHz）为复杂的卡尔曼滤波、实时避障和高频PID回路提供必要的计算余量，确保在严苛环境下具有卓越的飞行稳定性，远超F4/F7处理器的性能极限。',
  'fcesc.faq.q2': '三重冗余IMU如何提高无人机安全性？',
  'fcesc.faq.a2': '通过在不同总线上集成三个独立惯性传感器，飞控可以立即检测数据异常，并在几毫秒内切换到正常传感器，防止由振动或传感器漂移引起的灾难性故障。',
  'fcesc.faq.q3': 'FOC电调相比普通电调对重型无人机有什么优势？',
  'fcesc.faq.a3': 'FOC（磁场定向控制）电调提供更高效率、更低噪音、更平滑的电机控制，以及通过DroneCAN/UART的实时遥测（温度、转速、电流）。可延长飞行时间达10%，实现工业级运行可靠性。',
  'fcesc.faq.q4': 'CANI飞控电调系统是否符合NDAA要求？',
  'fcesc.faq.a4': '是的。CANI提供符合NDAA要求的硬件配置，满足政府和企业采购需求。请联系我们获取BlueUAS对标产品规格。',
  'fcesc.faq.q5': '可以为我的特定无人机平台定制飞控电调吗？',
  'fcesc.faq.a5': '当然可以。CANI提供完整的OEM/ODM定制服务，包括固件调优、连接器针脚、电压范围、电流额定值和安装形制。标准交付周期为15-30个工作日。',

