  // Per-SKU dynamic FAQs
  'fcEscDetail.faq.6in1.q1': '我的无人机何时应该使用六合一电调？',
  'fcEscDetail.faq.6in1.a1': '对于六旋翼飞行器配置而言，六合一电调是最佳选择，它提供了一个集中式电源枢纽，与六个独立的电调相比，简化了布线并减轻了整体重量。它非常适合需要高电流密度和空间利用率的工业平台。',
  'fcEscDetail.faq.6in1.q2': 'CANI 100A电调是否支持8S锂电池？',
  'fcEscDetail.faq.6in1.a2': '是的。我们的100A系列（分体式和堆叠式）采用高压MOSFET和低ESR电容器，可安全支持最高8S LiPo（33.6V），满足极高的推力需求。',
  'fcEscDetail.faq.stack.q1': '飞塔（Stack）相比分体组件有什么优势？',
  'fcEscDetail.faq.stack.a1': '飞塔将飞控和电调集成为一个紧凑单元，减少布线复杂度，节省重量，最大限度降低电磁干扰。这使装机更整洁、飞行更可靠。',
  'fcEscDetail.faq.stack.q2': '这款飞塔可以使用Betaflight和INAV吗？',
  'fcEscDetail.faq.stack.a2': '可以。所有CANI飞塔开箱即支持Betaflight固件，大多数型号还支持INAV和ArduPilot进行GPS自主任务飞行。',

  // EEAT Quality Statement
  'fcEscDetail.eeat.title': '品质保证',
  'fcEscDetail.eeat.statement': '每套CANI飞控和电调组合都经过48小时压力测试和工厂功率一致性校准，确保开箱即用，零故障。',
  'fcEscDetail.eeat.protocol': '支持SmartAudio v2.1和IRC Tramp协议，实现无缝OSD控制。',
  'fcEscDetail.eeat.protocolTitle': '协议兼容性',

  // Gimbal SEO Content
  'gimbal.seo.intro.title': '任务关键型数据的精准保障',
  'gimbal.seo.intro': '无人机的价值取决于它采集的数据质量。我们的三轴无刷云台系列为可见光、热成像和多光谱传感器提供终极增稳平台。采用高扭矩无刷电机和先进IMU融合算法，即使在7级大风条件下仍能确保±0.01°稳定精度。支持PWM、S.Bus、串口等标准协议，兼容各类飞控和机体。从轻量化碳纤维长航时云台到专业影视级重载云台，CANI为您的航空作业提供"稳定之手"。',
  'gimbal.techDetail.title': '集成与控制协议',
  'gimbal.techDetail': '本系列云台载荷采用三轴无刷增稳结构，角度抖动量±0.005°，俯仰-135°至+45°，支持360°全景拍摄。航空级铝合金材质，IP65防水防尘，工作温度-20°C~+55°C。支持网口/串口TTL/HDMI/SBUS等多种接口，兼容MAVLink协议与Pixhawk飞控系统，通用快拆接口实现即插即用集成。',
  'gimbal.faq.title': '常见疑问解答',
  'gimbal.faq.q1': 'CANI工业云台的增稳精度能达到多少？',
  'gimbal.faq.a1': '所有CANI三轴无刷云台通过高扭矩无刷电机和IMU融合算法，实现±0.005°至±0.01°增稳精度。即使在7级风或高速飞行机动中，也能确保画面纹丝不动。',
  'gimbal.faq.q2': '支持哪些控制协议和飞控系统？',
  'gimbal.faq.a2': '支持MAVLink、PWM、S.Bus、串口TTL协议，兼容Pixhawk、ArduPilot等开源飞控，通过网口、串口或SBUS接口连接。OEM项目可提供DJI SkyPort或自定义协议集成。',
  'gimbal.faq.q3': '能否集成第三方可见光或热成像相机？',
  'gimbal.faq.a3': '可以。CANI云台配备通用快拆接口，支持可见光、热成像（640×512）及多光谱相机集成。OEM/ODM服务提供定制减震板和线束，适配FLIR、DJI Zenmuse、Sony工业相机等第三方传感器。',
  'gimbal.faq.q4': '云台的承载能力和重量范围是多少？',
  'gimbal.faq.a4': '产品线涵盖115g超轻量单传感器云台（承载200g）到290g四传感器系统（承载500g）。如需搭载激光雷达或影视级相机等重型载荷，请联系我们获取定制重载增稳方案。',
  'gimbal.faq.q5': 'CANI云台在极端温度和雨天表现如何？',
  'gimbal.faq.a5': '全系列IP65防水防尘，工作温度-20°C至+55°C。在小雨、雪天、沙漠高温和高海拔环境中表现可靠。暴雨或海洋盐雾环境可提供额外防护方案。',
  'gimbal.faq.q6': 'CANI云台是否符合NDAA合规要求？',
  'gimbal.faq.a6': '是的。CANI云台载荷采用NDAA合规组件和数据安全协议制造，适用于全球政府、国防和关键基础设施巡检应用。',
