  'platforms.page.keywords': '工业级多旋翼平台,无人机集群载体,企业级无人机机架,Ardupilot兼容无人机,PX4兼容无人机,MAVLink多旋翼,冗余IMU飞控,C10集群套件,C20战术多旋翼,C30重载无人机平台,OEM ODM无人机厂家,无人机批量采购,CANI',
