  'platforms.hero.overview': 'CANI是专业的OEM/ODM无人机厂家，专注工业级多旋翼平台研发制造。产品配备冗余IMU飞控系统、MAVLink协议支持及任务优化机身设计。集群无人机载体（C10/C20/C30）载重能力从2kg到100kg+，续航最长55分钟，抗风7级——为全球企业级无人机解决方案而生。',

