  'products.anchor.aiModule': '查看AI模块',
  'aiModule.seo.title': '无人机AI模块与边缘计算载荷 | 计算机视觉 | CANI UAV',
  'aiModule.seo.description': '高性能无人机AI模块，驱动实时目标检测、智能跟踪与避障，搭载前沿边缘计算技术，赋能自主飞行任务。',
  'aiModule.seo.keywords': '无人机边缘计算模块,AI目标检测,计算机视觉处理器,自主飞行控制,NPU神经处理单元,无人机AI模块',
  'aiModule.back': '返回产品中心',
  'aiModule.hero.title': '无人机AI大脑与自主边缘计算模块',
  'aiModule.hero.desc': '赋能自主飞行：在智能空中机器人时代，AI模块是您任务的核心。我们的边缘计算载荷将标准无人机转变为自主智能系统，实现AI物体识别、精准着陆和智能集群。与CANI无人机生态系统完全兼容。',
  'aiModule.intro.title': 'AI边缘计算技术概述',
  'aiModule.intro.desc': 'CANI AI模块集成先进的计算机视觉与深度学习算法，支持实时目标检测、最高90km/h速度跟踪，延迟低于5ms，兼容CRSF、Sbus、MavLinkv2协议及BetaFlight、INAV、APM、PX4固件。',
  'aiModule.viewDetail': '查看技术详情',
