  'aiModule.tf2du.name': 'TF2DU 双光热成像AI视觉模块',
  'aiModule.tf2du.slogan': '双光谱全天候智能之眼',
  'aiModule.tf2du.subSlogan': '热红外+可见光 AI感知模块 TF2DU',
  'aiModule.tf2du.highlight.1': '热红外(IR)+可见光(EO)双光谱融合感知',
  'aiModule.tf2du.highlight.2': '2560×1440可见光 / 640×512热红外分辨率',
  'aiModule.tf2du.highlight.3': '热障碍检测：识别电力线、变压器等发热目标',
  'aiModule.tf2du.highlight.4': '全天候导航：全黑、浓雾、强光环境稳定感知',
  'aiModule.tf2du.desc.1': '双光谱融合：热红外与可见光传感器同时工作，即使在全黑、浓雾或强光直射环境下也能保持稳定的环境感知，提供多光谱态势感知能力。',
  'aiModule.tf2du.desc.2': '热障碍检测：能够识别电力线、变压器、活体目标等发热物体，提供传统视觉无法实现的避障能力，专为夜间巡检、森林防火监控和室内搜索设计。',
  'aiModule.tf2du.desc.3': 'AI边缘分析：内置目标识别算法实时分析热信号，支持自动跟踪热源或规避高温危险区，最大跟踪速度90km/h，延迟≤5ms。',
  'aiModule.tf2hd.name': 'TF2HD 高清AI视觉处理与目标跟踪模块',
  'aiModule.tf2hd.slogan': '高清智能视觉分析核心',
  'aiModule.tf2hd.subSlogan': '高性能HD AI视觉处理器 TF2HD',
  'aiModule.tf2hd.highlight.1': '原生高清视频流实时AI渲染与视觉反馈',
  'aiModule.tf2hd.highlight.2': '高算力NPU同时识别跟踪多个目标',
  'aiModule.tf2hd.highlight.3': '支持TensorFlow/PyTorch自定义AI检测模型部署',
  'aiModule.tf2hd.highlight.4': '毫秒级响应：从图像采集到AI决策全链路优化',
  'aiModule.tf2hd.desc.1': 'HD视频处理中心：支持原生高清视频流输入与实时AI渲染，为飞行控制系统提供高保真的视觉反馈，是构建自主作业无人机的核心算力载体。',
  'aiModule.tf2hd.desc.2': '高级神经处理：内置高算力NPU，能够同时识别并跟踪多个目标（车辆、行人、特定工业设备），实现自动化基础设施巡检、精准目标跟踪和实时语义分割。',
  'aiModule.tf2hd.desc.3': '低延迟智能：优化了从图像采集到AI决策的完整链路，确保在高速飞行中实现毫秒级响应速度，是追求真正认知自主的无人机平台的决定性引擎。',
  'aiModule.tf2a.name': 'TF2A 自主飞行AI模块与路径规划引擎',
  'aiModule.tf2a.slogan': '全自主飞行的战术大脑',
  'aiModule.tf2a.subSlogan': '自主飞行AI处理器 TF2A',
  'aiModule.tf2a.highlight.1': '自主路径规划：内置高性能导航算法，实时计算最优飞行路径',
  'aiModule.tf2a.highlight.2': '智能全方位避障：多传感器融合，复杂动态环境自主绕障',
  'aiModule.tf2a.highlight.3': '无GPS导航：基于视觉里程计定位，隧道/室内稳定飞行',
  'aiModule.tf2a.highlight.4': '边缘智能中枢：支持大规模神经网络推理与战术任务决策',
  'aiModule.tf2a.desc.1': '自主路径规划：作为无人机的"战术大脑"，TF2A使无人机超越简单遥控，进入真正的认知自主领域，在毫秒内完成复杂路径规划与实时决策。',
  'aiModule.tf2a.desc.2': '无GPS环境导航：支持基于视觉里程计（Visual Odometry）的定位技术，确保无人机在隧道、室内、地下等无信号环境下依然稳定飞行，是自主集群与全自动巡检编队的基础。',
  'aiModule.tf2a.desc.3': '通用协议适配：深度适配MAVLink等工业协议，无缝对接BetaFlight、INAV、APM、PX4等主流飞控系统，核心模组38×38×10mm，仅重37g，紧凑高效。',
