  'acc.canifmtdetail.k547': '联系我们',
  'acc.canifmtdetail.k548': '查看全部飞控/电调',
  'acc.elrsdetail.k549': '基于ExpressLRS协议的915MHz远距离无人机接收机。采用真多样性双电路设计，微秒级信号切换，支持超视距控制。',
  'acc.elrsdetail.k550': '仅0.6g的超微型ExpressLRS接收机。专为小型无人机与穿越机设计，采用915MHz Nano架构，支持远距离控制与低功耗管理，实现极致性能密度。',
  'acc.elrsdetail.k551': '支持1000Hz刷新率的超低延迟2.4G ELRS接收机。可选微型陶瓷天线设计，极致轻量，专为高速FPV竞速与近距离高精度无人机编队作业设计。',
  'acc.elrsdetail.k552': '集成了LNA低噪声放大器与100mW PA功率放大器的2.4G ELRS接收机。支持1000Hz高刷新率，解决2.4G远航回传丢包痛点，是中长距离巡检与FPV穿越的终极选择。',
  'acc.elrsdetail.k553': '专为915MHz远航设计的Moxon矩形定向天线。具备5.5dBi高增益与180°波束宽度，可提升ELRS控制距离50%以上，是超视距(BVLOS)飞行的核心增益配件。',
  'acc.elrsdetail.k554': '针对2.4GHz ISM频段优化的T型全向无人机天线。具备VSWR < 1.5的超低驻波比，提供稳定的垂直极化信号，是保障1000Hz高刷新率控制链路不丢包的核心基石。',
  'acc.elrsdetail.k555': '针对915MHz工业频段优化的T型全向天线。具备VSWR < 1.2的极低驻波比与360°面包圈场型，是远距离多角度巡检与复杂航线作业的理想选择。',
  'acc.fcescdetail.k556': 'CANI-Pixhawk4 工业级冗余飞控：重塑开源架构的可靠性基石',
  'acc.fcescdetail.k557': '了解三冗余传感器架构、EMI电磁隔离技术与PX4/ArduPilot生态深度适配',
  'acc.fcescdetail.k558': '定义紧凑型动力极限：CANI Stack-Mini F7-55A 飞速塔的技术演变与工业应用',
  'acc.fcescdetail.k559': '深入了解 F745 算力跨越、双向 DShot 动态谐波过滤与 55A 四合一电调散热工程',
  'acc.fcescdetail.k560': '技术白皮书',
