  'swarmpage.w200.k667': '亚毫米级精度室内动捕编队方案',
  'swarmpage.w200.k668': 'CANI W400 GPS旗舰集群套件',
  'swarmpage.w200.k669': '户外大规模RTK GPS集群协同',
  'swarmpage.w200.k670': '协同作业先锋：W200集群无人机——全栈分布式集群平台',
  'swarmpage.w200.k671': '探索W200分布式集群协议、数字网状通信与多智能体协同算法',
  'swarmpage.w200.k672': '开启您的集群无人机研究',
  'swarmpage.w200.k673': 'CANI W200套件提供开箱即用的UWB集群编队解决方案，具备厘米级定位精度，助力科研团队快速验证多智能体算法和集群智能协议。',
  'swarmpage.w300.k674': 'W300 旗舰级集群无人机平台 | 双天线RTK精密编队 | CANI长凌科技',
  'swarmpage.w300.k675': 'W300是旗舰级集群无人机，专为大规模协同编队飞行而设计。具备双天线RTK提供卓越航向精度、长航时续航、鲁棒数字网状通信链路，兼容MoCap动捕系统实现亚毫米级精度科研。',
  'swarmpage.w300.k676': 'W300高级集群无人机,专业编队飞行平台,双天线RTK集群,高性能集群智能,长航时编队无人机,企业级集群硬件,动捕集群,OptiTrack无人机',
  'swarmpage.w300.k677': 'W300 旗舰级高精度集群协同系统',
  'swarmpage.w300.k678': 'W300是长凌科技的旗舰级集群无人机平台，专为对大规模编队飞行精度和可靠性有极致要求的机构客户打造。配备双天线RTK实现卓越航向精度和抗磁场干扰能力，鲁棒数字网状通信确保数百节点间无缝低延迟协同，延长续航时间满足复杂长时间集群任务需求。',
  'swarmpage.w300.k679': '捕捉刷新率',
  'swarmpage.w300.k680': 'CANI W200 UWB集群套件',
  'swarmpage.w300.k681': '厘米级UWB定位，适用于室内外集群科研',
  'swarmpage.w300.k682': 'CANI W400 GPS旗舰集群套件',
  'swarmpage.w300.k683': '旗舰级集群智能：W300——企业级软硬一体化全栈平台',
  'swarmpage.w300.k684': '探索W300动态自愈Mesh组网、双天线RTK航向对准与群智协同算法',
  'swarmpage.w300.k685': '开启企业级集群研究',
  'swarmpage.w300.k686': 'CANI W300为科研团队和企业运营商提供最高精度集群平台。双天线RTK、长续航和动捕兼容，满足关键任务编队飞行需求。',
  'swarmpage.w400.k687': 'W400 重型集群无人机平台 | 大载荷长航时 | CANI长凌科技',
  'swarmpage.w400.k688': 'W400是重型集群无人机，专为大载荷任务和长航时飞行而设计。具备双天线RTK、IP防护等级、鲁棒数字网状通信和100 TOPS AI边缘计算，满足战术级集群智能需求。',
  'swarmpage.w400.k689': 'W400重型集群,工业重型集群无人机,长航时集群协同,多传感器集群载体,全天候集群无人机,战术级集群智能,GPS集群平台,六旋翼集群',
  'swarmpage.w400.k690': 'W400 重型大载荷集群系统',
