  'swarmPage.seo.title': '工业级无人机集群平台与集群技术 | CANI长凌科技',
  'swarmPage.seo.desc': 'CANI长凌科技提供专业无人机集群平台（W200/W300/W400），支持大规模集群协同任务。具备厘米级RTK定位、MAVLink网状通信、自主集群智能导航能力。',
  'swarmPage.seo.keywords': '无人机集群,集群智能,多机协同控制,集群编队,RTK定位,MAVLink自组网,自主集群导航,集群无人机套件',
  'swarmPage.hero.title': '一体化无人机集群解决方案与协同平台',
  'swarmPage.hero.subtitle': '厘米级RTK定位、MAVLink网状通信、一对多自主编队控制——为科研、国防和工业领域的大规模无人机协同提供下一代技术基础设施。',
  'swarmPage.feat.title': '核心集群技术',
  'swarmPage.f1.title': '多星座GNSS + RTK',
