  'swarmPage.f2.title': 'MAVLink网状通信',
  'swarmPage.f2.desc': '鲁棒的数字网状通信，支持低延迟广播、无人机间数据共享和去中心化集群协同，消除单点故障。',
  'swarmPage.f3.title': '开源ROS/PX4架构',
